/* ═══════════════════════════════════════════════════════════════════════
   THE LATE FIVE · the films the other rooms own
   ---------------------------------------------------------------------------
   These five are never on the first screen: each is reached by a tap into
   another room. They travel beside the page, not inside it, and are asked
   for once the first screen is up — so the door, its film and every card
   the first screen shows arrive first, exactly as before. Same films, same
   frames, same moments: the engine mounts each one the moment it lands.
   If this file cannot come, the house keeps its own stills and says nothing.
   ═══════════════════════════════════════════════════════════════════════ */
window.IVFILM_DATA = Object.assign(window.IVFILM_DATA || {}, {
  private_line:        "",
  early_door_home:     "",
  early_door_inside:   "",
  early_door_profile:  "",
  folio_quiet:         ""
});

/* mount at once anything already waiting on screen */
try { if (window.IVFILMS && IVFILMS.sweep) IVFILMS.sweep(); } catch (e) {}
